package com.goldenfalcons.sailinggps
data class SignalEvent(val id:Int,val secondsBeforeStart:Int,val title:String,val color:Int,val raised:Boolean,val flag:String,val hornPulses:List<Int>)
data class SignalFlagProfile(val id:String,val name:String,val events:List<SignalEvent>,val baseDurationMinutes:Int=5)
object SignalSequence {
    private fun e(id:Int,s:Int,t:String,f:String,c:Int,u:Boolean,vararg pulses:Int)=SignalEvent(id,s,t,c,u,f,pulses.toList())
    val profiles=listOf(
        SignalFlagProfile("class-p","Rule 26参考（クラス旗＋P旗）",listOf(e(0,300,"クラス旗を掲揚","級",android.graphics.Color.rgb(245,138,0),true,0),e(1,240,"P旗を掲揚","P",android.graphics.Color.rgb(23,105,255),true,0),e(2,60,"P旗を降下","P",android.graphics.Color.rgb(23,105,255),false,1),e(3,0,"クラス旗を降下","級",android.graphics.Color.rgb(245,138,0),false,0))),
        SignalFlagProfile("class-i","カスタム（クラス旗＋I旗）",listOf(e(0,300,"クラス旗を掲揚","級",android.graphics.Color.rgb(245,138,0),true,0),e(1,240,"I旗を掲揚","I",android.graphics.Color.rgb(245,211,40),true,0),e(2,60,"I旗を降下","I",android.graphics.Color.rgb(245,211,40),false,1),e(3,0,"クラス旗を降下","級",android.graphics.Color.rgb(245,138,0),false,0))),
        SignalFlagProfile("class-u","カスタム（クラス旗＋U旗）",listOf(e(0,300,"クラス旗を掲揚","級",android.graphics.Color.rgb(245,138,0),true,0),e(1,240,"U旗を掲揚","U",android.graphics.Color.rgb(215,44,50),true,0),e(2,60,"U旗を降下","U",android.graphics.Color.rgb(215,44,50),false,1),e(3,0,"クラス旗を降下","級",android.graphics.Color.rgb(245,138,0),false,0))),
        SignalFlagProfile("class-black","カスタム（クラス旗＋黒旗）",listOf(e(0,300,"クラス旗を掲揚","級",android.graphics.Color.rgb(245,138,0),true,0),e(1,240,"黒旗を掲揚","黒",android.graphics.Color.rgb(32,32,32),true,0),e(2,60,"黒旗を降下","黒",android.graphics.Color.rgb(32,32,32),false,1),e(3,0,"クラス旗を降下","級",android.graphics.Color.rgb(245,138,0),false,0))),
        SignalFlagProfile("class-p-i","カスタム（クラス旗＋P旗＋I旗）",listOf(e(0,300,"クラス旗を掲揚","級",android.graphics.Color.rgb(245,138,0),true,0),e(1,240,"P旗を掲揚","P",android.graphics.Color.rgb(23,105,255),true,0),e(2,180,"I旗を掲揚","I",android.graphics.Color.rgb(245,211,40),true,0),e(3,120,"I旗を降下","I",android.graphics.Color.rgb(245,211,40),false,0),e(4,60,"P旗を降下","P",android.graphics.Color.rgb(23,105,255),false,1),e(5,0,"クラス旗を降下","級",android.graphics.Color.rgb(245,138,0),false,0))),
        SignalFlagProfile("appendix-v","Appendix V参考（音声のみ）",listOf(e(0,180,"3分前・長音×3","♪",android.graphics.Color.DKGRAY,true,1,1,1),e(1,120,"2分前・長音×2","♪",android.graphics.Color.DKGRAY,true,1,1),e(2,90,"1分30秒前・長音＋短音×3","♪",android.graphics.Color.DKGRAY,true,1,0,0,0),e(3,60,"1分前・長音","♪",android.graphics.Color.DKGRAY,true,1),e(4,30,"30秒前・短音×3","♪",android.graphics.Color.DKGRAY,true,0,0,0),e(5,20,"20秒前・短音×2","♪",android.graphics.Color.DKGRAY,true,0,0),e(6,10,"10秒前・短音","♪",android.graphics.Color.DKGRAY,true,0),e(7,5,"5秒前・短音","♪",android.graphics.Color.DKGRAY,true,0),e(8,4,"4秒前・短音","♪",android.graphics.Color.DKGRAY,true,0),e(9,0,"スタート・短音","♪",android.graphics.Color.DKGRAY,true,0)),baseDurationMinutes=3)
    )
    fun events(minutes:Int,profileIndex:Int=0):List<SignalEvent>{val p=profiles.getOrElse(profileIndex){profiles[0]};val d=minutes.coerceAtLeast(1);return p.events.map{it.copy(secondsBeforeStart=(it.secondsBeforeStart*d.toDouble()/p.baseDurationMinutes).toInt())}}
    fun nextIndex(left:Double,minutes:Int,profileIndex:Int=0):Int{val es=events(minutes,profileIndex);return es.indexOfFirst{left>=it.secondsBeforeStart}.let{if(it<0)es.lastIndex else it}}
    fun untilNext(left:Double,index:Int,minutes:Int,profileIndex:Int=0)=kotlin.math.ceil(left-events(minutes,profileIndex)[index].secondsBeforeStart).toInt()
}